WITH catalog_sales_enhanced AS (SELECT cs.cs_bill_customer_sk AS customer_sk, cs.cs_promo_sk AS promo_sk, cs.cs_net_paid_inc_tax AS net_paid, cs.cs_net_profit AS net_profit, NULL AS store_name, 'catalog' AS channel FROM catalog_sales cs), store_sales_enhanced AS (SELECT ss.ss_customer_sk AS customer_sk, ss.ss_promo_sk AS promo_sk, ss.ss_net_paid_inc_tax AS net_paid, ss.ss_net_profit AS net_profit, s.s_store_name AS store_name, 'store' AS channel FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk), unified_sales AS (SELECT * FROM catalog_sales_enhanced UNION ALL SELECT * FROM store_sales_enhanced), promo_detail AS (SELECT p.p_promo_sk, p.p_promo_name, p.p_discount_active FROM promotion p) SELECT us.customer_sk, SUM(us.net_paid) AS total_net_paid, SUM(us.net_profit) AS total_net_profit, COUNT(*) AS transaction_cnt, MAX(CASE WHEN us.channel = 'catalog' THEN 1 ELSE 0 END) AS has_catalog_sales, MAX(CASE WHEN us.channel = 'store' THEN 1 ELSE 0 END) AS has_store_sales, MAX(us.store_name) AS store_name, pd.p_promo_name, CASE WHEN SUM(us.net_paid) > 50000 THEN 'VIP' WHEN SUM(us.net_paid) BETWEEN 20000 AND 50000 THEN 'GOLD' ELSE 'SILVER' END AS customer_tier, RANK() OVER (ORDER BY SUM(us.net_profit) DESC) AS profit_rank FROM unified_sales us LEFT JOIN promo_detail pd ON us.promo_sk = pd.p_promo_sk GROUP BY us.customer_sk, pd.p_promo_name HAVING SUM(us.net_paid) > 0 ORDER BY profit_rank LIMIT 100
